Object.assign(PROPS2, {
  /* coupe de pierre (les enfants de la vache rousse) */
  ttStoneCup(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, [0, -1], 0.02)), s = h / 100; P.shape([[q[0] - 7 * s, q[1] - 7 * s], [q[0] + 7 * s, q[1] - 7 * s], [q[0] + 5 * s, q[1] + 2 * s], [q[0] - 5 * s, q[1] + 2 * s]], 'k2y2', lw * 0.7); P.fill([[q[0] - 6 * s, q[1] - 7 * s], [q[0] + 6 * s, q[1] - 7 * s], [q[0] + 6 * s, q[1] - 5 * s], [q[0] - 6 * s, q[1] - 5 * s]], 'b5y1', {}); P.line([[q[0] + 7 * s, q[1] - 5 * s], [q[0] + 10 * s, q[1] - 3 * s], [q[0] + 6 * s, q[1]]], lw * 0.7); },
  /* cruche neuve qu'on va tremper */
  ttVessel(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, [0, 1], 0.05)), s = h / 140; P.shape([[q[0] - 4 * s, q[1] - 12 * s], [q[0] + 4 * s, q[1] - 12 * s], [q[0] + 3 * s, q[1] - 8 * s], [q[0] + 8 * s, q[1] - 3 * s], [q[0] + 7 * s, q[1] + 6 * s], [q[0] + 3 * s, q[1] + 9 * s], [q[0] - 3 * s, q[1] + 9 * s], [q[0] - 7 * s, q[1] + 6 * s], [q[0] - 8 * s, q[1] - 3 * s], [q[0] - 3 * s, q[1] - 8 * s]], 'r6y5k1', lw * 0.7); P.line([[q[0] - 7 * s, q[1]], [q[0] + 7 * s, q[1]]], lw * 0.5, { ink: 3, lvl: 5 }); },
  /* panier de poteries sur la tête */
  ttPots(P, A, J, M, h, t, lw, F) { const c = M([J.head[0] + J.hu[0] * 0.1, J.head[1] + J.hu[1] * 0.1]), s = h / 140; P.shape([[c[0] - 16 * s, c[1]], [c[0] + 16 * s, c[1]], [c[0] + 13 * s, c[1] - 9 * s], [c[0] - 13 * s, c[1] - 9 * s]], 'y5r3k2', lw * 0.8); for (let i = 0; i < 5; i++) P.line([[c[0] - 14 * s + i * 7 * s, c[1] - 8 * s], [c[0] - 13 * s + i * 7 * s, c[1]]], lw * 0.4); for (const [dx, tn] of [[-8, 'r6y5k1'], [2, 'r5y6k2'], [10, 'r6y4k1']]) { const b = [c[0] + dx * s, c[1] - 9 * s]; P.shape([[b[0] - 4 * s, b[1]], [b[0] - 5 * s, b[1] - 7 * s], [b[0] - 2 * s, b[1] - 12 * s], [b[0] + 2 * s, b[1] - 12 * s], [b[0] + 5 * s, b[1] - 7 * s], [b[0] + 4 * s, b[1]]], tn, lw * 0.6); } },
  /* corbeille de prémices */
  ttBasket(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, [0, -1], 0.02)), s = h / 140; P.shape([[q[0] - 12 * s, q[1] - 8 * s], [q[0] + 12 * s, q[1] - 8 * s], [q[0] + 9 * s, q[1] + 4 * s], [q[0] - 9 * s, q[1] + 4 * s]], 'y5r3k2', lw * 0.7); for (let i = 0; i < 4; i++) P.line([[q[0] - 10 * s + i * 7 * s, q[1] - 7 * s], [q[0] - 9 * s + i * 6 * s, q[1] + 3 * s]], lw * 0.4); for (const [dx, dy, tn] of [[-7, -10, 'r7b4'], [0, -12, 'y8r2'], [7, -10, 'r7y4'], [-3, -15, 'y6b5'], [4, -15, 'r6b5']]) P.shape(P.disc(q[0] + dx * s, q[1] + dy * s, 3.4 * s, 8), tn, lw * 0.4); },
  /* les deux pains de Chavouot */
  ttLoaves(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, [0, -1], 0.02)), s = h / 140; for (const dy of [0, -6]) P.shape(smooth([[q[0] - 13 * s, q[1] + dy * s], [q[0] - 12 * s, q[1] + (dy - 5) * s], [q[0] + 12 * s, q[1] + (dy - 6) * s], [q[0] + 13 * s, q[1] + dy * s]], 2), 'y7r4k1', lw * 0.6); },
  /* rouleau déroulé entre les deux mains */
  ttScroll(P, A, J, M, h, t, lw, F) {
    const a = M(J.aN.t), b = M(J.aF.t), s = h / 140, lo = Math.min(a[0], b[0]) - 4 * s, hi = Math.max(a[0], b[0]) + 4 * s, y = (a[1] + b[1]) / 2;
    P.shape([[lo, y - 12 * s], [hi, y - 14 * s], [hi, y + 10 * s], [lo, y + 12 * s]], 'y1', lw * 0.6);
    for (let i = 0; i < 5; i++) P.line([[lo + 5 * s, y - 7 * s + i * 4 * s], [hi - 5 * s, y - 8 * s + i * 4 * s]], lw * 0.35);
    for (const x of [lo, hi]) { P.shape([[x - 3 * s, y - 16 * s], [x + 3 * s, y - 16 * s], [x + 3 * s, y + 14 * s], [x - 3 * s, y + 14 * s]], 'y3r2k1', lw * 0.6); P.line([[x, y - 22 * s], [x, y + 20 * s]], lw * 1.4, { ink: 3, lvl: 7, taper: 0 }); }
  },
  /* rouleau qu'on roule pour le refermer : les deux cylindres se rapprochent */
  ttRollUp(P, A, J, M, h, t, lw, F) {
    const a = M(J.aN.t), b = M(J.aF.t), s = h / 140, k = 0.5 + 0.5 * Math.sin(t * 0.8), c = (a[0] + b[0]) / 2, half = (8 + 10 * k) * s, y = (a[1] + b[1]) / 2;
    P.shape([[c - half, y - 12 * s], [c + half, y - 13 * s], [c + half, y + 10 * s], [c - half, y + 11 * s]], 'y1', lw * 0.6);
    for (let i = 0; i < 4; i++) P.line([[c - half + 3 * s, y - 7 * s + i * 4.5 * s], [c + half - 3 * s, y - 8 * s + i * 4.5 * s]], lw * 0.35);
    for (const x of [c - half, c + half]) { P.shape([[x - 4 * s, y - 15 * s], [x + 4 * s, y - 15 * s], [x + 4 * s, y + 13 * s], [x - 4 * s, y + 13 * s]], 'y3r2k1', lw * 0.6); P.line([[x, y - 21 * s], [x, y + 19 * s]], lw * 1.4, { ink: 3, lvl: 7, taper: 0 }); }
  },
  ttTowel(P, A, J, M, h, t, lw) { const q = M(J.aN.w); P.shape([[q[0] - h * 0.045, q[1] - h * 0.012], [q[0] + h * 0.045, q[1] - h * 0.012], [q[0] + h * 0.04, q[1] + h * 0.13], [q[0] - h * 0.035, q[1] + h * 0.13]], 'y1b1', lw * 0.7); P.line([[q[0] - h * 0.038, q[1] + h * 0.1], [q[0] + h * 0.04, q[1] + h * 0.1]], lw * 0.9, { ink: 2 }); },
  ttLamp(P, A, J, M, h, t, lw, F, u, n, add) { const q = M(add(A.t, [0, -1], 0.02)); P.halo(q[0], q[1] - h * 0.06, h * 0.16, ['y1', 'y2', 'y3r1']); P.shape([[q[0] - h * 0.04, q[1]], [q[0] + h * 0.045, q[1] - h * 0.01], [q[0] + h * 0.03, q[1] - h * 0.03], [q[0] - h * 0.03, q[1] - h * 0.03]], 'r5y6k2', lw * 0.7); Lib.flame(P, q[0] + h * 0.035, q[1] - h * 0.03, h * 0.03, h * 0.07, t * 1.3, { noKnock: true }); }
});
