const ttCypress = (P, x, y, hh = 120, tn = 'y4b6k3') => { const b = P.I(x, y, 0); P.shape(smooth([[b[0] - 9, b[1]], [b[0] - 12, b[1] - hh * 0.45], [b[0], b[1] - hh], [b[0] + 12, b[1] - hh * 0.45], [b[0] + 9, b[1]]], 2), tn, 1); P.line([[b[0], b[1] - 4], [b[0] - 2, b[1] - hh * 0.8]], 0.5); };
/* un bassin creusé : parois, marches, eau au niveau -wl ; (X0,Y0) coin arrière */
const ttPool = (P, X0, X1, Y0, Y1, D, wl, o = {}) => {
  const I = (a, b, c) => P.I(a, b, c), ctx = P.ctx, rim = [I(X0, Y0, 0), I(X1, Y0, 0), I(X1, Y1, 0), I(X0, Y1, 0)];
  ctx.save(); ctx.beginPath(); ctx.moveTo(rim[0][0], rim[0][1]); for (const p of rim.slice(1)) ctx.lineTo(p[0], p[1]); ctx.closePath(); ctx.clip();
  P.shape([I(X0, Y0, 0), I(X1, Y0, 0), I(X1, Y0, -D), I(X0, Y0, -D)], o.wall || 'y3r2k2', 0.9);
  P.shape([I(X0, Y0, 0), I(X0, Y1, 0), I(X0, Y1, -D), I(X0, Y0, -D)], tadd(o.wall || 'y3r2k2', 'k1'), 0.9);
  for (let z = -10; z > -D; z -= 10) { P.line([I(X0, Y0, z), I(X1, Y0, z)], 0.3); P.line([I(X0, Y0, z), I(X0, Y1, z)], 0.3); }
  const n = o.steps || 4, sw = o.sw || 60, sd = (Y1 - Y0) * 0.8 / n, sh = D / (n + 1);
  const step = i => { const y = Y1 - (i + 1) * sd, z = -(i + 1) * sh; P.box(X0, y, -D, sw, sd, z + D, o.step || 'y3r2k1', 0.6); };
  for (let i = n - 1; i >= 0; i--) if (-(i + 1) * sh < -wl) step(i);
  const wat = [I(X0, Y0, -wl), I(X1, Y0, -wl), I(X1, Y1, -wl), I(X0, Y1, -wl)]; P.fill(wat, o.water || 'b5y2', { noKnock: true }); P.outline(wat, 0.8);
  for (let i = n - 1; i >= 0; i--) if (-(i + 1) * sh >= -wl) step(i);
  ctx.restore();
  P.outline(rim, 1.3);
};
/* vigne en rangées de ceps */
const ttVines = (P, x, y, w, d, rows, n = 6) => {
  for (let r = 0; r < rows; r++) { const yy = y + r * d / Math.max(1, rows - 1); P.line([P.I(x, yy, 22), P.I(x + w, yy, 22)], 0.6); for (let i = 0; i <= n; i++) { const xx = x + i * w / n; P.line([P.I(xx, yy, 0), P.I(xx, yy, 24)], 1.1, { ink: 3, lvl: 7 }); const c = P.I(xx, yy, 26); P.shape(Lib.bumpy(P, c[0], c[1] - 4, 14, 9, 6), (i + r) % 2 ? 'y4b5k2' : 'y5b5k1', 0.7); if ((i + r) % 3 === 0) P.fill(P.disc(c[0] + 4, c[1] + 4, 3, 8), 'r6b5', {}); } }
};
/* pièce intérieure (sol, deux murs, frises) */
const ttRoom = (P, o) => {
  const L = P.L, H = o.h || 230;
  Lib.platform(P, o.floor || 'y4r3k2', 'y4r3k2', { h: 46, pebbles: false });
  for (let v = 45; v < L; v += 45) P.line([P.I(v, 0, 0), P.I(v, L, 0)], 0.45);
  Lib.walls(P, { l: o.wl, r: tadd(o.wl, 'k1'), cut: 'y4r3k2' }, { h: H });
  Lib.wallL(P, 0, 0, L, 26, tadd(o.wl, 'r1k2'), 0.7); Lib.wallR(P, 0, 0, L, 26, tadd(o.wl, 'r1k3'), 0.7);
  Lib.wallL(P, 0, H - 30, L, 9, o.band || 'b5y2', 0.5); Lib.wallR(P, 0, H - 30, L, 9, o.band || 'b5y2', 0.5);
  for (let v = 0; v < L; v += 18) { Lib.wallL(P, v + 4, H - 28, 8, 5, o.band2 || 'y7r2', 0); Lib.wallR(P, v + 4, H - 28, 8, 5, o.band2 || 'y7r2', 0); }
};
const ttWinR = (P, x, z, w, h, sky, o = {}) => {
  Lib.wallR(P, x - 7, z - 7, w + 14, h + 14, 'r4y5k3', 1); Lib.wallR(P, x, z, w, h, sky, 0.8);
  if (o.stars) { const r = rng(o.stars); for (let i = 0; i < 6; i++) { const q = P.I(x + (0.1 + r() * 0.8) * w, 0.5, z + (0.2 + r() * 0.7) * h); Lib.star(P, q[0], q[1], 2 + r() * 2.5, r() > 0.5 ? 'y7' : 'y4'); } }
  if (o.moon) { const q = P.I(x + w * 0.3, 0.5, z + h * 0.7); P.shape(P.disc(q[0], q[1], o.moon, 20), 'y4', 0.6); P.fill(P.disc(q[0] - 3, q[1] + 2, o.moon * 0.3, 10), 'y5k1', { noKnock: true }); }
  P.line([P.I(x + w / 2, 0.5, z), P.I(x + w / 2, 0.5, z + h)], 1.8); P.line([P.I(x, 0.5, z + h * 0.58), P.I(x + w, 0.5, z + h * 0.58)], 1.4);
  P.box(x - 9, 0.5, z - 11, w + 18, 10, 4, 'r4y5k2', 0.8);
};
const ttNiche = (P, y, z, tn = 'y3r2k3') => { Lib.archL(P, y, z, 30, 34, tn, 0.8); Lib.lamp(P, 6, y + 15, z + 2, 0.5); };
/* le grand vase : (x, y, z) = pied ; s = échelle */
const ttVase = (P, x, y, z, s) => {
  const b = P.I(x, y, z), X = (a, c) => [b[0] + a * s, b[1] - c * s];
  const body = [X(-14, 0), X(-22, 8), X(-34, 40), X(-36, 64), X(-30, 84), X(-17, 96), X(-14, 104), X(-20, 112), X(-20, 116), X(20, 116), X(20, 112), X(14, 104), X(17, 96), X(30, 84), X(36, 64), X(34, 40), X(22, 8), X(14, 0)];
  P.shape(smooth(body, 2), 'r5y6k2', 1.2);
  P.shape(smooth([X(-30, 70), X(30, 70), X(33, 56), X(-33, 56)], 1), 'k6r3', 0);
  for (let i = 0; i < 9; i++) { const a = X(-30 + i * 7.5, 58), c = X(-27 + i * 7.5, 68); P.fill([[a[0], a[1]], [c[0], a[1]], [(a[0] + c[0]) / 2, c[1]]], 'y7r3', {}); }
  P.line(smooth([X(-35, 44), X(0, 40), X(35, 44)], 1).slice(0, 12), 1, { ink: 3, lvl: 6 });
  P.line([X(-34, 30), X(34, 30)], 0.9, { ink: 1, lvl: 7 });
  for (const sg of [-1, 1]) P.line([X(sg * 16, 102), X(sg * 30, 104), X(sg * 32, 92), X(sg * 26, 84)], 2.4, { ink: 3, lvl: 7, taper: 0 });
  P.shape([X(-20, 116), X(20, 116), X(18, 119), X(-18, 119)], 'y2r1', 0.8);
  P.line([X(-30, 50), X(-26, 80)], 2, { ink: 0, lvl: 2 });
};

